	private static void exerciseMorselOwnerClose() throws Exception {
		int workers = 2;
		CountDownLatch ready = new CountDownLatch(workers);
		ThreadLocal<Boolean> resourcesClosed = new ThreadLocal<>();
		var executor = Executors.newFixedThreadPool(workers);
		try (var execution = new LmdbNativeMorselExecutor<Integer>(workers, workers, new NativeCancellationToken());
				var context = QueryExecutionContext.activateReplaySafepoint(() -> {
				}, () -> () -> () -> {
					assertThat(resourcesClosed.get()).as("native work cleanup precedes owner cleanup").isTrue();
					try {
						execution.close();
					} catch (IOException failure) {
						throw new UncheckedIOException(failure);
					}
				})) {
			execution.start(executor, (index, owner) -> {
				resourcesClosed.set(false);
				try {
					ready.countDown();
					ready.await();
					owner.emit(index);
				} finally {
					resourcesClosed.set(true);
				}
			});
			execution.finish();
		} finally {
			executor.shutdownNow();
		}
	}

