	static boolean hasCause(Throwable problem, Throwable expected) {
		if (problem == null) {
			return false;
		}
		if (problem == expected || hasCause(problem.getCause(), expected)) {
			return true;
		}
		for (Throwable suppressed : problem.getSuppressed()) {
			if (hasCause(suppressed, expected)) {
				return true;
			}
		}
		return false;
	}
